```javascript
/**
 * Creates a debounced function that delays invoking `func` until after
 * `wait` milliseconds have elapsed since the last time the debounced
 * function was invoked.
 *
 * @param {Function} func - The function to debounce.
 * @param {number} wait - The number of milliseconds to delay.
 * @returns {Function} A new debounced function with a `.cancel()` method
 *                     to cancel pending invocations and a `.flush()` method
 *                     to immediately invoke the pending call.
 *
 * @example
 * // Debounce a window resize handler so it only fires after
 * // the user has stopped resizing for 250ms.
 * const handleResize = debounce(() => {
 *   console.log('Resized!', window.innerWidth, window.innerHeight);
 * }, 250);
 *
 * window.addEventListener('resize', handleResize);
 *
 * // Later, to cancel any pending invocation:
 * handleResize.cancel();
 */
function debounce(func, wait) {
  let timeoutId = null;

  /**
   * The debounced function.
   *
   * @this {*} The context (`this`) of the original call.
   * @param {...*} args - Arguments passed to the debounced function.
   * @returns {void}
   */
  function debounced(...args) {
    const context = this;

    clearTimeout(timeoutId);

    timeoutId = setTimeout(() => {
      timeoutId = null;
      func.apply(context, args);
    }, wait);
  }

  /**
   * Cancels any pending debounced invocation.
   *
   * @returns {void}
   */
  debounced.cancel = function () {
    clearTimeout(timeoutId);
    timeoutId = null;
  };

  /**
   * Immediately invokes the debounced function if there is a pending call.
   *
   * @returns {void}
   */
  debounced.flush = function () {
    if (timeoutId !== null) {
      clearTimeout(timeoutId);
      timeoutId = null;
      func.apply(this, debounced._args);
    }
  };

  return debounced;
}
```

### How It Works

| Concept | Detail |
|---|---|
| **Core idea** | Each call resets a `setTimeout` timer. `func` only fires once the timer expires without being reset. |
| **`.cancel()`** | Clears the pending timer — useful for cleanup (e.g., `componentWillUnmount`). |
| **`.flush()`** | Forces the pending call to execute immediately. |
| **`this` binding** | Preserved via `.apply(context, args)` so the debounced function works correctly as an event handler or method. |

### Quick Usage Example

```javascript
// Search input that fires an API call only after the user stops typing
const searchInput = document.getElementById('search');

const fetchResults = debounce((query) => {
  console.log('Searching for:', query);
  // fetch(`/api/search?q=${query}`);
}, 300);

searchInput.addEventListener('input', (e) => {
  fetchResults(e.target.value);
});
```

In this example, rapid keystrokes are coalesced into a single call 300 ms after the user stops typing, reducing unnecessary API requests.
